    def update(self, dt):
        self.time += dt
        zs = self.game.get_effects().get_zones()
        for i in range(len(zs)):
            self.born_of(zs[i])
        ws = self.game.get_effects().get_walkers()
        for i in range(len(ws)):
            self.born_of(ws[i])
        ds = self.game.get_effects().get_drones()
        for i in range(len(ds)):
            self.born_of(ds[i])
        hz = self.game.get_effects().get_hazards()
        for i in range(len(hz)):
            self.born_of(hz[i])
        self.prune_timer -= dt
        if self.prune_timer <= 0:
            self.prune_timer = 1.5
            _j_remove_if(_j.key_set(self.born), _j.Fn(lambda o: (not WorldFx.is_live(o))))
        for i in range((len(self.sings) - 1), -1, -1):
            if (self.time - self.sings[i].t0) > (self.sings[i].hold + 0.5):
                self.sings.pop(i)
    @staticmethod
    def is_live(o):
        if isinstance(o, TrackZone):
            return o.is_alive()
        if isinstance(o, TrackWalker):
            return o.is_alive()
        if isinstance(o, Drone):
            return o.is_alive()
        if isinstance(o, NodeHazard):
            return o.is_alive()
        return False
    def on_ability_event(self, ev):
        """Feeds an ability event: Gemini's Argon Singularity has no sim entity, so it is recognised here."""
        if ev.a is None:
            return
        for t in self.game.get_tower_manager().get_towers():
            if ((t.get_type() is not TowerType.GEMINI) or (t.get_ability() is None)) or (not t.get_ability().has('holdTime')):
                continue
            a = t.get_ability()
            if (abs((ev.radius - a.p('radius', (-1)))) > 0.01) or (ev.rgb != t.get_type().primary_rgb):
                continue
            s = WorldFx.Sing()
            s.at = ev.a
            s.radius = ev.radius
            s.t0 = self.time
            s.hold = a.p('holdTime')
            s.rgb = ev.rgb
            _j_add(self.sings, s)
            return
    def born_of(self, o):
        b = self.born.get(o)
        if b is None:
            _j_put(self.born, o, self.time)
            return self.time
        return b
    def paint_ground(self, g):
        hz = self.game.get_effects().get_hazards()
        i = 0
        n = min(len(hz), self.cap())
        while i < n:
            self.draw_grid(g, hz[i])
