    @staticmethod
    def since_ability(t):
        """Seconds since the tower's ability was activated (large if it was not recently)."""
        if t.get_ability() is None:
            return 99.0
        return t.get_ability().cooldown - t.get_ability_cooldown_remaining()
    def draw_hero_ground(self, g, t):
        """Ability auras, support links and buff rings drawn under the enemies."""
        c = t.get_position()
        ty = t.get_type()
        if (ty is TowerType.ZETHOS) and ZethosBehavior.is_collapsing(t):
            R = t.effective_range(self.game)
            k = 0
            while k < (2 if (self.lod >= 2) else 4):
                ph = _j.fmod(((self.time * 0.6) + (k / 4.0)), 1.0)
