    def blob(self, cx, cy, r, wob, seed, ph):
        """Wobbly closed blob (paint splotch)."""
        self.path.reset()
        n = (10 if (self.lod >= 2) else 18)
        for i in range(n + 1):
            a = (((math.pi * 2) * i) / n)
            rr = (r * ((1 + (wob * math.sin((((a * 3) + (seed * 1.7)) + ph)))) + ((wob * 0.6) * math.sin((((a * 5) + (seed * 0.9)) - (ph * 0.7))))))
            x = (cx + (math.cos(a) * rr))
            y = (cy + (math.sin(a) * rr))
            if i == 0:
                self.path.move_to(x, y)
            else:
                self.path.line_to(x, y)
        self.path.close_path()
        return self.path
    @staticmethod
    def seed_of(o):
        return (_j.identity_hash(o) >> 3) & 0xff
    def draw_zone(self, g, z):
        age = (self.time - self.born_of(z))
        pop = WorldFx.ease_out(_j.dmin(1, (age / 0.3)))
        fade = (1 if z.permanent else _j.dmax(0, _j.dmin(1, (z.get_remaining() / 0.6))))
        R = (z.radius * pop)
        if R < 1:
            return
        cx = z.center.x
        cy = z.center.y
        A = (255 * fade)
        kind = ('' if (z.kind is None) else z.kind)
        _sw1 = kind
        if _sw1 == 'paint':
            self.zone_paint(g, z, cx, cy, R, A)
        elif _sw1 == 'loop':
            self.zone_loop(g, z, cx, cy, R, A)
        elif _sw1 == 'tornado':
            self.zone_tornado(g, z, cx, cy, R, A)
        elif _sw1 == 'vortex':
            self.zone_vortex(g, z, cx, cy, R, A)
        elif _sw1 == 'outpaint':
            self.zone_outpaint(g, z, cx, cy, R, A)
        elif _sw1 == 'tempest':
            self.zone_tempest(g, z, cx, cy, R, A)
        elif _sw1 == 'blackhole':
            self.zone_black_hole(g, z, cx, cy, R, A)
        else:
            self.oval(g, cx, cy, R, R, WorldFx.col(z.rgb, (A * 0.25)), WorldFx.col(WorldFx.INK, (A * 0.8)), 2.5)
            self.ring(g, cx, cy, (R - 3), WorldFx.col(z.rgb, (A * 0.9)), 2)
    def zone_paint(self, g, z, cx, cy, R, A):
        """DALL-E paint: a glossy wobbling splotch with droplets and (armour crack) a few dark cracks."""
        seed = WorldFx.seed_of(z)
        body = WorldFx.mix(z.rgb, Color.WHITE, 0.15)
        b = self.blob(cx, cy, (R * 0.92), 0.07, seed, (self.time * 1.6))
        g.set_color(WorldFx.col(body, (A * 0.42)))
        g.fill(b)
        g.set_stroke(self.st(3))
        g.set_color(WorldFx.col(WorldFx.INK, (A * 0.85)))
        g.draw(b)
        inner = self.blob(cx, cy, (R * 0.6), 0.1, (seed + 3), ((-self.time) * 1.3))
        g.set_color(WorldFx.col(WorldFx.mix(z.rgb, Color.WHITE, 0.45), (A * 0.35)))
        g.fill(inner)
        if self.lod >= 2:
            return
        for i in range(4):
            a = _j.fmod(((seed * 0.37) + (i * 1.7)), (math.pi * 2))
            d = (R * (1.0 + (0.08 * math.sin(((self.time * 3) + i)))))
            self.oval(g, (cx + (math.cos(a) * d)), (cy + (math.sin(a) * d)), (4.5 - (i * 0.6)), (4.5 - (i * 0.6)), WorldFx.col(body, (A * 0.8)), WorldFx.col(WorldFx.INK, (A * 0.85)), 2)
        if self.lod == 0:
            self.gloss(g, (cx - (R * 0.15)), (cy - (R * 0.1)), (R * 1.1))
            if z.armor_crack:
                g.set_stroke(self.st(1.8))
                g.set_color(WorldFx.col(WorldFx.INK, (A * 0.7)))
                for i in range(3):
                    a = ((seed * 0.5) + (i * 2.1))
                    r0 = (R * 0.15)
                    r1 = (R * 0.7)
                    self.path.reset()
                    self.path.move_to((cx + (math.cos(a) * r0)), (cy + (math.sin(a) * r0)))
                    self.path.line_to((cx + ((math.cos((a + 0.25)) * (r0 + r1)) * 0.5)), (cy + ((math.sin((a + 0.25)) * (r0 + r1)) * 0.5)))
                    self.path.line_to((cx + (math.cos((a - 0.1)) * r1)), (cy + (math.sin((a - 0.1)) * r1)))
                    g.draw(self.path)
    def zone_loop(self, g, z, cx, cy, R, A):
        """Sora loop: a double clock ring with rotating tick marks and two chasing arrowheads."""
